OutstandingBalanceByDueDate = {
	init: async function (app, container) {
		app = app || session.app;
		container = container || $(".component[name=OutstandingBalanceByDueDate]");
		const firstDay = (new Date()).toISOString().split("T")[0];
		var lastDay = new Date();
		lastDay.setDate(lastDay.getDate() + 75);
		lastDay = lastDay.toISOString().split("T")[0];

		$("[name=outstandingHeader]", container).html($("[name=outstandingHeader]", container).html() + " " + firstDay + " - " + lastDay);
        var data = await OutstandingBalanceByDueDate.getData(app, firstDay, lastDay);
		 OutstandingBalanceByDueDate.initChart(container, data, app.Config.B2B.Currencies);
	},

    getData: async function (app, firstDay, lastDay) {
		return await api.get(`B2B/ActiveTransaction/FromSystem(SystemId='${app.Config.B2B.SourceSystem}')?$apply=filter(DueDate ge ${firstDay} and DueDate le ${lastDay})/groupby((DueDate,CurrencyId), aggregate(Value with sum as UnpaidValue))`);
    },

	initChart: function (container, data, currencies) {
		var categories = data.map(i => i.DueDate);
		console.log({ component: "OutstandingBalanceByDueDate", data: data });
		var args = {
			showLegend: true,
			valueTemplate: "#: kendo.toString(value, type.aggregateMoneyFormat)#",
			tooltipTemplate: "#= series.name #: #= kendo.toString(value, type.aggregateMoneyFormat) #",
			categoryTemplate: "#= kendo.toString(new Date(value), type.dateFormat) #",
			series: currencies.map(cur => ({
				field: "UnpaidValue",
				categoryField: "DueDate",
				name: "[resource_displayname[UnpaidValue]] (" + cur + ")",
				data: categories.map(c => data.filter(r => r.DueDate === c && r.CurrencyId === cur)).flat()
			})),
			categories: categories,
			max: data.map(i => i.UnpaidValue).sort((a, b) => b - a)[0],
			type: "column"
		};
		return (new Chart($("[name=chart]", container), args)).init();
	}
}
